-- Batch 4 summary corrections (25 rows). Original AI text preserved in summary_original.
begin;
update provisions set summary_original = coalesce(summary_original, ai_summary), ai_summary = 'The permit requires that when you permanently replace an engine, you must analyze whether Regulation Number 26, Part B, Section I.D.4 applies. That rule requires rich-burn natural gas engines over 500 hp built or modified before February 1, 2009 to install and operate a non-selective catalyst reduction system and air-fuel controller, and requires, as a state-only requirement, all lean-burn natural gas engines over 500 hp to install and operate an oxidation catalyst. The permit directs you to check specific exemptions and control requirements in Sections I.D.1, I.D.4.a.(i)(B)-(C), I.D.4.a.(i)(A), I.D.4.a.(i), I.D.4.b.(i), and I.D.4.c for engines at or above 1,000 hp.', summary_status = 'approved', reviewed_by = 'Claude (AI second-pass review; summary corrected, per owner instruction 2026-09-19)', reviewed_at = now() where id = 'sec-gp02-ATTACHMENT-A-5-4' and summary_status = 'pending';
update provisions set summary_original = coalesce(summary_original, ai_summary), ai_summary = 'If the stationary source where the engine is located is a true minor source, the owner or operator must calculate and record the annual emissions from each engine on a calendar-year basis to demonstrate compliance with the annual emission limits.', summary_status = 'approved', reviewed_by = 'Claude (AI second-pass review; summary corrected, per owner instruction 2026-09-19)', reviewed_at = now() where id = 'sec-gp02-IV-C-1-a-(i)' and summary_status = 'pending';
update provisions set summary_original = coalesce(summary_original, ai_summary), ai_summary = 'If the engine is at a synthetic minor or major source, the permit requires you to calculate emissions monthly and track annual emissions from each engine as a rolling 12-month total, recalculated at the end of every month using the prior 12 months'' data. During the first year of operation, compliance is based on cumulative emissions from all months operated so far.', summary_status = 'approved', reviewed_by = 'Claude (AI second-pass review; summary corrected, per owner instruction 2026-09-19)', reviewed_at = now() where id = 'sec-gp02-IV-C-1-a-(ii)' and summary_status = 'pending';
update provisions set summary_original = coalesce(summary_original, ai_summary), ai_summary = 'The permit requires you to calculate engine emissions using the methods spelled out in this section, using the same emission factors, site rated horsepower, brake-specific fuel consumption (BSFC), and lower fuel heat value (LHV) that the Division approved in your most recent registration. Equations 1 through 4 are annual calculations and should be adjusted to the appropriate time period (monthly or annual) as required by Section IV.C.1.a.', summary_status = 'approved', reviewed_by = 'Claude (AI second-pass review; summary corrected, per owner instruction 2026-09-19)', reviewed_at = now() where id = 'sec-gp02-IV-C-1-b' and summary_status = 'pending';
update provisions set summary_original = coalesce(summary_original, ai_summary), ai_summary = 'The permit requires that total controlled HAP emissions from all equipment at the stationary source not exceed 8.0 tons per year for any single HAP and 20.0 tons per year for all HAPs combined, per Regulation Number 3, Part B, Section II.A.4.', summary_status = 'approved', reviewed_by = 'Claude (AI second-pass review; summary corrected, per owner instruction 2026-09-19)', reviewed_at = now() where id = 'sec-gp05-II-B-2' and summary_status = 'pending';
update provisions set summary_original = coalesce(summary_original, ai_summary), ai_summary = 'The permit requires you to calculate annual emissions from diesel engines based on fuel consumption using one of five equations (Eq. 2.a through Eq. 2.e), each with its own emission factor format: lb per million BTU (Eq. 2.a), lb per hp-hr (Eq. 2.b), g per hp-hr (Eq. 2.c), lb per 1000 gallons (Eq. 2.d), or g per kW-hr (Eq. 2.e). You must use the emission factor, horsepower, fuel usage, lower heating value, and runtime that match what you specified in your most recent registration.', summary_status = 'approved', reviewed_by = 'Claude (AI second-pass review; summary corrected, per owner instruction 2026-09-19)', reviewed_at = now() where id = 'sec-gp06-IV-C-1-b-(ii)' and summary_status = 'pending';
update provisions set summary_original = coalesce(summary_original, ai_summary), ai_summary = '"Storage Tank" means any fixed-roof storage vessel or series of storage vessels manifolded together by liquid line, with "storage vessel" defined the same way as in the federal NSPS OOOO and OOOOa standards (40 CFR Part 60).', summary_status = 'approved', reviewed_by = 'Claude (AI second-pass review; summary corrected, per owner instruction 2026-09-19)', reviewed_at = now() where id = 'sec-gp08-I-A-1' and summary_status = 'pending';
update provisions set summary_original = coalesce(summary_original, ai_summary), ai_summary = 'The permit requires that if a combustion device is used to comply with any requirement of this permit, the owner or operator must ensure the device meets the specific requirements set out in the conditions that follow.', summary_status = 'approved', reviewed_by = 'Claude (AI second-pass review; summary corrected, per owner instruction 2026-09-19)', reviewed_at = now() where id = 'sec-gp09-II-D' and summary_status = 'pending';
update provisions set summary_original = coalesce(summary_original, ai_summary), ai_summary = 'The permit requires any lean-burn natural gas-fired reciprocating internal combustion engine rated 500 horsepower or greater and located in an ozone nonattainment area to install and operate an oxidation catalyst. This condition references Regulation Number 26, Part B, Section I.B.2.', summary_status = 'approved', reviewed_by = 'Claude (AI second-pass review; summary corrected, per owner instruction 2026-09-19)', reviewed_at = now() where id = 'sec-gp09-IV-B-6' and summary_status = 'pending';
update provisions set summary_original = coalesce(summary_original, ai_summary), ai_summary = 'The permit requires operators to use the current Air Pollution Emission Notice forms in accordance with the Source Grouping requirements in Regulation Number 3, Part A, Section II.B.4 (Reference: Regulation Number 3, Part B, Section III.E). Once your registration under this general permit expires, you cannot rely on it to provide enforceable emission limits.', summary_status = 'approved', reviewed_by = 'Claude (AI second-pass review; summary corrected, per owner instruction 2026-09-19)', reviewed_at = now() where id = 'sec-gp10-I-H' and summary_status = 'pending';
update provisions set summary_original = coalesce(summary_original, ai_summary), ai_summary = 'The permit requires you to track the gas volume for each routine or predictable venting event if you''re using a pounds-per-million-standard-cubic-feet (lb/MMscf) emission factor. You can do this either by monitoring the parameters your registration approval letter specifies and calculating the volume, or by directly measuring the volume with a flow meter.', summary_status = 'approved', reviewed_by = 'Claude (AI second-pass review; summary corrected, per owner instruction 2026-09-19)', reviewed_at = now() where id = 'sec-gp11-III-A-2-b' and summary_status = 'pending';
update provisions set summary_original = coalesce(summary_original, ai_summary), ai_summary = 'Under this Alternative Operating Scenario, test results and calculations must be submitted to the Division within 30 calendar days of the test, or within 60 days if the test demonstrates compliance with NSPS or MACT requirements. All test results must be maintained and made available to the Division upon request.', summary_status = 'approved', reviewed_by = 'Claude (AI second-pass review; summary corrected, per owner instruction 2026-09-19)', reviewed_at = now() where id = 'sec-gp12-ATTACHMENT-A-4-2' and summary_status = 'pending';
update provisions set summary_original = coalesce(summary_original, ai_summary), ai_summary = 'The permit requires you to perform routine or predictable gas venting emissions activities between October 1 and April 30, when practicable.', summary_status = 'approved', reviewed_by = 'Claude (AI second-pass review; summary corrected, per owner instruction 2026-09-19)', reviewed_at = now() where id = 'sec-gp12-V-K-3' and summary_status = 'pending';
update provisions set summary_original = coalesce(summary_original, ai_summary), ai_summary = 'The permit requires you to visually inspect air pollution control equipment used on storage tanks, hydrocarbon liquids loadout, gas venting from separators, or routine/predictable emissions. You must follow the inspection schedule in Table 2 (ECD monitoring frequency), and at a minimum the inspections must include the items specified in the sub-provisions that follow this condition.', summary_status = 'approved', reviewed_by = 'Claude (AI second-pass review; summary corrected, per owner instruction 2026-09-19)', reviewed_at = now() where id = 'sec-gp12-VI-E-5' and summary_status = 'pending';
update provisions set summary_original = coalesce(summary_original, ai_summary), ai_summary = 'The permit requires that for each natural gas-fired engine with a catalytic emission control device, the owner or operator must meet the conditions set out in the following sub-paragraphs of this permit condition (VI.F.5.a through VI.F.5.f). The citation to Regulation Number 3, Part B, Section III.E. is the regulatory authority for this condition, not a separate source containing the requirements.', summary_status = 'approved', reviewed_by = 'Claude (AI second-pass review; summary corrected, per owner instruction 2026-09-19)', reviewed_at = now() where id = 'sec-gp12-VI-F-5' and summary_status = 'pending';
update provisions set summary_original = coalesce(summary_original, ai_summary), ai_summary = 'Manufacturers of emergency stationary compression-ignition engines rated below 37 kW (50 HP) must certify their 2007 model year engines to the Tier 2 emission standards for new nonroad CI engines at the appropriate power rating (in 40 CFR part 1039, appendix I) for all pollutants, plus the smoke standards in 40 CFR 1039.105 that apply to model year 2007 engines.', summary_status = 'approved', reviewed_by = 'Claude (AI second-pass review; summary corrected, per owner instruction 2026-09-19)', reviewed_at = now() where id = 'sec-iiii-60.4202-(a)-(1)-(i)' and summary_status = 'pending';
update provisions set summary_original = coalesce(summary_original, ai_summary), ai_summary = 'Manufacturers of emergency stationary compression-ignition engines rated below 37 kW (50 HP) must certify their 2008 model year and later engines to the certification emission standards for new nonroad CI engines in 40 CFR 1039.104, 1039.105, 1039.107, 1039.115, and Table 2 to this subpart.', summary_status = 'approved', reviewed_by = 'Claude (AI second-pass review; summary corrected, per owner instruction 2026-09-19)', reviewed_at = now() where id = 'sec-iiii-60.4202-(a)-(1)-(ii)' and summary_status = 'pending';
update provisions set summary_original = coalesce(summary_original, ai_summary), ai_summary = 'If you modify or reconstruct an emergency stationary compression-ignition internal combustion engine (CI ICE) covered by Subpart IIII, you must meet the emission standards in paragraphs (a) through (e) of this section that correspond to the model year, maximum engine power, and displacement of the modified or reconstructed engine.', summary_status = 'approved', reviewed_by = 'Claude (AI second-pass review; summary corrected, per owner instruction 2026-09-19)', reviewed_at = now() where id = 'sec-iiii-60.4205-(f)' and summary_status = 'pending';
update provisions set summary_original = coalesce(summary_original, ai_summary), ai_summary = 'If you operate a stationary compression-ignition internal combustion engine (CI ICE) with a displacement of less than 30 liters per cylinder in Guam, American Samoa, or the Commonwealth of the Northern Mariana Islands, you must meet the applicable emission standards in §§ 60.4202 and 60.4205.', summary_status = 'approved', reviewed_by = 'Claude (AI second-pass review; summary corrected, per owner instruction 2026-09-19)', reviewed_at = now() where id = 'sec-iiii-60.4215-(a)' and summary_status = 'pending';
update provisions set summary_original = coalesce(summary_original, ai_summary), ai_summary = 'Table 4 lists which sections of the EPA mobile-source certification regulations (40 CFR Parts 1048, 1065, and 1068) apply to manufacturers who voluntarily certify stationary spark-ignition engines to the emission standards in Table 1 of Subpart JJJJ. Most of Parts 1048, 1065, and 1068 apply, but the table specifically excludes certain sections—for example, evaporative emission standards (1048.105), on-board diagnostics (1048.205(c)), in-use testing (1048 subpart E), natural-gas test fuel specs (1065.715), and the three hardship provisions in Part 1068 (sections 245, 250, and 255). Deterioration-factor provisions in 1048.205(n) and 1048.240(b)(c)(d) both apply, and for 1048.205(n) the table notes an exception as indicated in § 60.4247(c).', summary_status = 'approved', reviewed_by = 'Claude (AI second-pass review; summary corrected, per owner instruction 2026-09-19)', reviewed_at = now() where id = 'sec-jjjj-TABLE-4' and summary_status = 'pending';
update provisions set summary_original = coalesce(summary_original, ai_summary), ai_summary = 'This section defines the terms used in Subpart ZZZZ. Key definitions include: **Emergency stationary RICE** means an engine operated to provide power or mechanical work during an emergency (such as when utility power is interrupted or to pump water during a fire or flood) and that complies with the operating conditions in § 63.6640(f) (an engine that does not comply with § 63.6640(f) is not an emergency stationary RICE). **Area source** means any stationary source of HAP that is not a major source. **Major source** has special aggregation rules for oil and gas facilities – emissions from individual wells and their associated equipment, and from pipeline compressor or pump stations, are not aggregated with other similar units even if they are nearby or under common control. **Spark ignition** means a gasoline engine or any engine with a spark plug and operating characteristics similar to the Otto cycle; dual-fuel engines using less than 2 parts diesel to 100 parts total fuel (energy basis, annual average) are spark ignition. **Compression ignition** means an engine that is not spark ignition. **Rich burn engine** means a four-stroke spark ignition engine where the manufacturer''s recommended air/fuel ratio divided by stoichiometric ratio at full load is ≤1.1, or (if no manufacturer recommendation exists) where exhaust oxygen at full load is ≤2 percent. **Lean burn engine** means any spark ignition engine (two-stroke or four-stroke) that does not meet the rich burn definition. **Limited use stationary RICE** means an engine that operates less than 100 hours per year. **Deviation** includes any failure to meet an emission or operating limit, any permit term implementing this subpart, or the general duty to minimize emissions, including during malfunction.', summary_status = 'approved', reviewed_by = 'Claude (AI second-pass review; summary corrected, per owner instruction 2026-09-19)', reviewed_at = now() where id = 'sec-zzzz-63.6675' and summary_status = 'pending';
update provisions set summary_original = coalesce(summary_original, ai_summary), ai_summary = 'This table sets out the requirements for existing compression-ignition (CI) engines at a major HAP source and existing spark-ignition (SI) engines 500 HP or smaller at a major HAP source. Emergency and black-start CI engines must change oil and filter every 500 hours or within 1 year plus 30 days (whichever comes first), inspect the air cleaner every 1,000 hours or within 1 year plus 30 days (whichever comes first), and inspect hoses and belts every 500 hours or within 1 year plus 30 days (whichever comes first). Non-emergency, non-black-start CI engines under 100 HP follow similar maintenance schedules but with oil changes every 1,000 hours or within 1 year plus 30 days. Non-emergency, non-black-start CI engines from 100 to 300 HP must limit CO to 230 ppmvd or less at 15 percent oxygen; those from 300 to 500 HP must limit CO to 49 ppmvd or less or reduce CO by 70 percent or more; and those over 500 HP must limit CO to 23 ppmvd or less or reduce CO by 70 percent or more. Emergency and black-start SI engines must change oil and filter every 500 hours or within 1 year plus 30 days, inspect spark plugs every 1,000 hours or within 1 year plus 30 days, and inspect hoses and belts every 500 hours or within 1 year plus 30 days. Non-emergency, non-black-start SI engines under 100 HP that are not 2SLB (two-stroke lean-burn) must change oil and filter every 1,440 hours or within 1 year plus 30 days, inspect spark plugs every 1,440 hours or within 1 year plus 30 days, and inspect hoses and belts every 1,440 hours or within 1 year plus 30 days; the same items apply every 4,320 hours for non-emergency, non-black-start 2SLB SI engines under 100 HP. Non-emergency, non-black-start engines from 100 to 500 HP must meet exhaust concentration limits at 15 percent oxygen: CO of 225 ppmvd or less for 2SLB engines, CO of 47 ppmvd or less for 4SLB engines, formaldehyde of 10.3 ppmvd or less for 4SRB engines, and CO of 177 ppmvd or less for engines burning landfill or digester gas equal to 10 percent or more of annual gross heat input. During startup, engines must minimize idle time and limit startup to the period needed for safe loading, not to exceed 30 minutes, after which the non-startup limits apply. Footnotes allow emergency engines to delay work practices during an emergency or where performing them would pose an unacceptable risk under law (with reporting of any such delay), allow an oil analysis program under § 63.6625(i) or (j) to extend the oil-change interval, and allow petitions to the Administrator under 40 CFR 63.6(g) for alternative work practices.', summary_status = 'approved', reviewed_by = 'Claude (AI second-pass review; summary corrected, per owner instruction 2026-09-19)', reviewed_at = now() where id = 'sec-zzzz-TABLE-2c' and summary_status = 'pending';
update provisions set summary_original = coalesce(summary_original, ai_summary), ai_summary = 'Table 2d sets out the requirements for existing stationary reciprocating internal combustion engines (RICE) at area sources of hazardous air pollutants (HAP). For non-emergency compression-ignition (CI) engines 300 HP or smaller, you must change oil and filter every 1,000 hours or within one year plus 30 days (whichever comes first), inspect the air cleaner every 1,000 hours or within one year plus 30 days and replace as necessary, and inspect hoses and belts every 500 hours or within one year plus 30 days and replace as necessary; during startup, minimize idle time and limit startup to 30 minutes. For non-emergency CI engines between 300 and 500 HP, you must either limit CO in the exhaust to 49 ppmvd at 15 percent oxygen or reduce CO emissions by 70 percent or more. For non-emergency CI engines over 500 HP, you must either limit CO to 23 ppmvd at 15 percent oxygen or reduce CO by 70 percent or more. Emergency CI engines and black start CI engines must change oil and filter every 500 hours or within one year plus 30 days, inspect the air cleaner every 1,000 hours or within one year plus 30 days, and inspect hoses and belts every 500 hours or within one year plus 30 days. Emergency spark-ignition (SI) engines, black start SI engines, and certain non-emergency four-stroke lean-burn (4SLB) and four-stroke rich-burn (4SRB) engines over 500 HP that operate 24 hours or less per year must change oil and filter every 500 hours or within one year plus 30 days, inspect spark plugs every 1,000 hours or within one year plus 30 days, and inspect hoses and belts every 500 hours or within one year plus 30 days. Non-emergency 2SLB engines follow the same three items every 4,320 hours or within one year plus 30 days; non-emergency 4SLB and 4SRB engines 500 HP or smaller, and engines burning landfill or digester gas equal to 10 percent or more of annual gross heat input, every 1,440 hours or within one year plus 30 days; and non-emergency remote 4SLB and 4SRB engines over 500 HP every 2,160 hours or within one year plus 30 days. Non-emergency 4SLB engines over 500 HP that are not remote and operate more than 24 hours per year must install an oxidation catalyst, and the equivalent 4SRB engines must install NSCR. Footnotes allow an oil analysis program under § 63.6625(i) or (j) to extend the oil-change interval, and allow emergency engines to delay the management practices during an emergency or where performing them would pose an unacceptable risk under law, with any such delay reported.', summary_status = 'approved', reviewed_by = 'Claude (AI second-pass review; summary corrected, per owner instruction 2026-09-19)', reviewed_at = now() where id = 'sec-zzzz-TABLE-2d' and summary_status = 'pending';
update provisions set summary_original = coalesce(summary_original, ai_summary), ai_summary = 'This table lays out how you demonstrate continuous compliance with emission limits and other requirements under this subpart. It covers different categories of engines (2SLB, 4SLB, 4SRB, and CI) at major and area sources, both new/reconstructed and existing, emergency and non-emergency, and at various horsepower thresholds. For engines reducing CO or formaldehyde using an oxidation catalyst or NSCR, you typically must conduct periodic performance tests (semiannually, annually, or every 8,760 hours/3–5 years depending on the engine category), collect and maintain catalyst inlet temperature data as 4-hour rolling averages within the limits established during your performance test, and measure pressure drop across the catalyst monthly to confirm it stays within the established range. If you''re not using a catalyst, you collect and maintain approved operating parameter data (if any) as 4-hour rolling averages within the limits from your performance test. Some engines using CEMS must collect 1-hour averages, demonstrate the required percent reduction or concentration limit, and conduct an annual RATA plus daily and periodic data quality checks per 40 CFR part 60 appendices. Certain existing emergency, black start, and smaller non-emergency engines at major or area sources must follow work or management practices—either the manufacturer''s emission-related operation and maintenance instructions or your own maintenance plan consistent with good air pollution control practice. For some area-source 4SLB and 4SRB engines over 500 HP that run more than 24 hours per year, you must conduct annual compliance demonstrations and either maintain catalyst inlet temperature 4-hour rolling averages within specified ranges (greater than 450 °F and at or below 1350 °F for oxidation catalyst on 4SLB; at or above 750 °F and at or below 1250 °F for NSCR on 4SRB) or immediately shut the engine down if the inlet temperature exceeds the upper limit. The annual demonstration must show a CO reduction of 93 percent or more or CO of 47 ppmvd or less at 15 percent oxygen for 4SLB engines, and for 4SRB engines a CO reduction of 75 percent or more, CO of 270 ppmvd or less at 15 percent oxygen, or a THC reduction of 30 percent or more. Non-emergency 4SRB engines of 5,000 brake HP or more at a major source must conduct semiannual formaldehyde performance tests showing the required formaldehyde reduction or a THC reduction of 30 percent or more. A footnote allows semiannual performance tests to drop to annual after two consecutive compliant tests, returning to semiannual after any failed test or deviation from an operating limitation.', summary_status = 'approved', reviewed_by = 'Claude (AI second-pass review; summary corrected, per owner instruction 2026-09-19)', reviewed_at = now() where id = 'sec-zzzz-TABLE-6' and summary_status = 'pending';
update provisions set summary_original = coalesce(summary_original, ai_summary), ai_summary = '**Row 1:** If you own certain existing non-emergency engines (100–500 HP at major sources, CI engines over 500 HP at major sources, 4SRB engines over 500 HP at major sources, CI engines over 300 HP at area sources) or certain new/reconstructed non-emergency engines (over 500 HP at major sources, or 4SLB engines 250–500 HP at major sources), you must submit a compliance report semiannually (or annually if the engine is limited-use and subject to numerical emission limits). The report must state either that there were no deviations from emission or operating limits and no periods when your continuous monitoring system (CMS, including CEMS and CPMS) was out-of-control, or if there were deviations or out-of-control periods, include the information required by § 63.6650(d) and (e); if you had a malfunction, include the information in § 63.6650(c)(4).

**Row 2:** If you own a new or reconstructed non-emergency engine that combusts landfill gas or digester gas equivalent to 10 percent or more of the gross heat input on an annual basis, you must submit an annual report. The report must include the fuel flow rate of each fuel and the heating values used in your calculations demonstrating that landfill or digester gas provides at least 10 percent of gross heat input annually, the operating limits in your federally enforceable permit and any deviations from them, and any problems or errors suspected with the meters.

**Row 3:** If you own an existing non-emergency, non-black start 4SLB or 4SRB engine over 500 HP at an area source of HAP that is not a remote engine and operates more than 24 hours per calendar year, you must submit a compliance report semiannually under § 63.6650(b)(1)-(5) and (i) containing the results of the annual compliance demonstration, if one was conducted during the reporting period.

**Row 4:** If you own an emergency engine that operates for the purposes specified in § 63.6640(f)(4)(ii), you must submit an annual report containing the information in § 63.6650(h)(1), according to § 63.6650(h)(2)-(3) and (i).', summary_status = 'approved', reviewed_by = 'Claude (AI second-pass review; summary corrected, per owner instruction 2026-09-19)', reviewed_at = now() where id = 'sec-zzzz-TABLE-7' and summary_status = 'pending';
commit;
